   "fact": "Bold black title reads 'Increasing Regional Air Quality Recovery from 2018 to 2023'."
  },
  {
   "location": "center plot area",
   "fact": "A single solid blue line connects six points, one per year from 2018 to 2023."
  },
  {
   "location": "line shape",
   "fact": "The line starts near the top left at 2018, drops to its lowest point at 2019, rises to its highest point at 2020, then steps down and remains nearly flat through 2021, 2022, and 2023."
  },
  {
   "location": "right side of line",
   "fact": "The 2023 endpoint sits slightly below the 2021 and 2022 levels and is clearly above the 2019 low but below the 2018 and 2020 peaks."
  },
  {
   "location": "axes",
   "fact": "Vertical axis is labeled 'Recovery Score'; horizontal axis is labeled 'Year' with tick labels 2018 through 2023."
  }
 ],
 "printed_facts": [
  {
   "location": "y-axis",
   "fact": "Numeric tick labels from bottom to top: 0, 400, 800, 1,200, 1,600, 2,000, 2,400, 2,800."
  },
  {
   "location": "x-axis",
   "fact": "Year tick labels: 2018, 2019, 2020, 2021, 2022, 2023."
  },
  {
   "location": "title",
   "fact": "'Increasing Regional Air Quality Recovery from 2018 to 2023'."
  },
  {
   "location": "form context",
   "fact": "Assessment window field: '2018-2023 air-quality trend review'."
  },
  {
